questions.solution:
def cached_tokens(prev_ids, ids, breakpoint):
    """Tokens of `ids` read from the cache written by `prev_ids`, given a cache breakpoint after
    the first `breakpoint` tokens. The cache matches the whole prefix up to the breakpoint or nothing."""
    if breakpoint <= 0 or len(prev_ids) < breakpoint or len(ids) < breakpoint:
        return 0
    return breakpoint if list(prev_ids[:breakpoint]) == list(ids[:breakpoint]) else 0
